 public async Task MarkScorecardDeferredAsync(string runId,string diagnostic,CancellationToken ct=default)
 {
  if(await HasScoreCorrectionAsync(runId,ct)){await MarkScoreCorrectionDeliveryAsync(runId,diagnostic,false,ct);return;}
  await using var c=await OpenAsync(ct);await using var tx=c.BeginTransaction(false);RunResponse run=await ReadRunAsync(c,tx,runId,ct)??throw new PersistenceIntegrityException("Scoring run missing.");DateTimeOffset now=timeProvider.GetUtcNow();await using(var delivery=Command(c,tx,"UPDATE ScorecardDeliveries SET Status='AwaitingDependency',AttemptCount=AttemptCount+1,Diagnostic=$diagnostic,UpdatedUtc=$now WHERE ScorecardId=(SELECT ScorecardId FROM Scorecards WHERE RunId=$run) AND NOT EXISTS(SELECT 1 FROM ScorecardReceipts sr WHERE sr.ScorecardId=ScorecardDeliveries.ScorecardId);")){Add(delivery,"$diagnostic",diagnostic);Add(delivery,"$now",Format(now));Add(delivery,"$run",runId);if(await delivery.ExecuteNonQueryAsync(ct)!=1)throw new PersistenceIntegrityException("Scorecard delivery checkpoint is unavailable.");}await using(var stage=Command(c,tx,"UPDATE RunStages SET Status=$status,Diagnostics=$diagnostic,EndedUtc=NULL WHERE RunId=$run AND Stage=$stage;")){Add(stage,"$status",StageStatus.AwaitingDependency.ToString());Add(stage,"$diagnostic",diagnostic);Add(stage,"$run",runId);Add(stage,"$stage",(int)RunStageKind.S9Score);await stage.ExecuteNonQueryAsync(ct);}await UpdateRunAsync(c,tx,runId,RunStatus.AwaitingDependency,RunStageKind.S9Score,now,diagnostic,null,ct);await AppendAuditAsync(c,tx,run.ScenarioId,"scorecard.deferred",runId,CanonicalJson.Serialize(new{diagnostic}),ct);await tx.CommitAsync(ct);
 }
 public async Task FailScorecardAsync(string runId,string diagnostic,CancellationToken ct=default)
 {
  if(await HasScoreCorrectionAsync(runId,ct)){await MarkScoreCorrectionDeliveryAsync(runId,diagnostic,true,ct);return;}
  await using var c=await OpenAsync(ct);await using var tx=c.BeginTransaction(false);RunResponse? run=await ReadRunAsync(c,tx,runId,ct);if(run is null||run.Status==RunStatus.Failed){await tx.CommitAsync(ct);return;}DateTimeOffset now=timeProvider.GetUtcNow();await using(var delivery=Command(c,tx,"UPDATE ScorecardDeliveries SET Status='Failed',AttemptCount=AttemptCount+1,Diagnostic=$diagnostic,UpdatedUtc=$now WHERE ScorecardId=(SELECT ScorecardId FROM Scorecards WHERE RunId=$run);")){Add(delivery,"$diagnostic",diagnostic);Add(delivery,"$now",Format(now));Add(delivery,"$run",runId);await delivery.ExecuteNonQueryAsync(ct);}await using(var stage=Command(c,tx,"UPDATE RunStages SET Status=$status,Diagnostics=$diagnostic,EndedUtc=$now WHERE RunId=$run AND Stage=$stage;")){Add(stage,"$status",StageStatus.Failed.ToString());Add(stage,"$diagnostic",diagnostic);Add(stage,"$now",Format(now));Add(stage,"$run",runId);Add(stage,"$stage",(int)RunStageKind.S9Score);await stage.ExecuteNonQueryAsync(ct);}await UpdateRunAsync(c,tx,runId,RunStatus.Failed,RunStageKind.S9Score,now,diagnostic,now,ct);await AppendAuditAsync(c,tx,run.ScenarioId,"scorecard.failed",runId,CanonicalJson.Serialize(new{diagnostic}),ct);await tx.CommitAsync(ct);
 }
 public async Task CompleteScorecardAsync(ScorecardDraft card,string receiptJson,CancellationToken ct=default)
 {
  if(card.ScoringModelVersion==ScoreCorrection.ModelVersion){await CompleteScoreCorrectionAsync(card,receiptJson,ct);return;}
  string receiptHash=DeterministicIdentity.Sha256(receiptJson);await using var c=await OpenAsync(ct);await using var tx=c.BeginTransaction(false);RunResponse run=await ReadRunAsync(c,tx,card.RunId,ct)??throw new PersistenceIntegrityException("Scoring run missing.");if(run.Status==RunStatus.Scored){await tx.CommitAsync(ct);return;}ScorecardDraft persisted=await ReadScorecardAsync(c,tx,card.RunId,ct)??throw new PersistenceIntegrityException("Scorecard missing.");if(persisted.InputSha256!=card.InputSha256||persisted.OutputSha256!=card.OutputSha256)throw new PersistenceIntegrityException("Scorecard changed before callback completion.");string? existing=await ReadScorecardReceiptAsync(c,tx,card.ScorecardId,ct);if(existing is null){await using var receipt=Command(c,tx,"INSERT INTO ScorecardReceipts(ScorecardId,CanonicalReceiptJson,ReceiptHash,ReceivedUtc)VALUES($id,$json,$hash,$now);");Add(receipt,"$id",card.ScorecardId);Add(receipt,"$json",receiptJson);Add(receipt,"$hash",receiptHash);Add(receipt,"$now",Format(timeProvider.GetUtcNow()));await receipt.ExecuteNonQueryAsync(ct);}else if(existing!=receiptJson)throw new PersistenceIntegrityException("Immutable scorecard receipt changed.");DateTimeOffset now=timeProvider.GetUtcNow();await using(var delivery=Command(c,tx,"UPDATE ScorecardDeliveries SET Status='Completed',AttemptCount=AttemptCount+1,Diagnostic=NULL,UpdatedUtc=$now WHERE ScorecardId=$id;")){Add(delivery,"$now",Format(now));Add(delivery,"$id",card.ScorecardId);await delivery.ExecuteNonQueryAsync(ct);}string output=CanonicalJson.Serialize(new{card.ScorecardId,card.ScoringModelVersion,card.InputSha256,card.OutputSha256,card.HeadlineMetric,metricCount=card.Metrics.Count,status="Scored",receiptHash});var audit=await AppendAuditAsync(c,tx,run.ScenarioId,"scorecard.published",card.ScorecardId,output,ct);await using(var stage=Command(c,tx,"UPDATE RunStages SET Status=$status,OutputJson=$output,OutputHash=$hash,EndedUtc=$now,Diagnostics=NULL,PreviousAuditHash=$previous WHERE RunId=$run AND Stage=$stage;")){Add(stage,"$status",StageStatus.Completed.ToString());Add(stage,"$output",output);Add(stage,"$hash",DeterministicIdentity.Sha256(output));Add(stage,"$now",Format(now));Add(stage,"$previous",audit.PreviousHash);Add(stage,"$run",card.RunId);Add(stage,"$stage",(int)RunStageKind.S9Score);if(await stage.ExecuteNonQueryAsync(ct)!=1)throw new PersistenceIntegrityException("S9 completion checkpoint failed.");}await UpdateRunAsync(c,tx,card.RunId,RunStatus.Scored,RunStageKind.S9Score,now,null,now,ct);await tx.CommitAsync(ct);
 }
 static async Task<ScorecardDraft?> ReadScorecardAsync(SqliteConnection c,SqliteTransaction? tx,string runId,CancellationToken ct)
 {
  string id,scenario,reveal,version,inputHash,input,headline,output,outputHash,validText;await using(var query=Command(c,tx,"SELECT ScorecardId,ScenarioId,RevealId,ScoringModelVersion,InputSha256,CanonicalInputJson,HeadlineMetric,CanonicalOutputJson,OutputSha256,CreatedValidTimeUtc FROM Scorecards WHERE RunId=$run;")){Add(query,"$run",runId);await using var reader=await query.ExecuteReaderAsync(ct);if(!await reader.ReadAsync(ct))return null;id=reader.GetString(0);scenario=reader.GetString(1);reveal=reader.GetString(2);version=reader.GetString(3);inputHash=reader.GetString(4);input=reader.GetString(5);headline=reader.GetString(6);output=reader.GetString(7);outputHash=reader.GetString(8);validText=reader.GetString(9);}
  if(DeterministicIdentity.Sha256(input)!=inputHash||DeterministicIdentity.Sha256(output)!=outputHash||id!=DeterministicIdentity.Create("scorecard-v1",runId,reveal,version,inputHash))throw new PersistenceIntegrityException("Scorecard integrity failure.");AnalysisScorecardRequest request=JsonSerializer.Deserialize<AnalysisScorecardRequest>(output,CanonicalJson.SerializerOptions)??throw new PersistenceIntegrityException("Scorecard output invalid.");var metrics=new List<ScorecardMetric>();await using(var rows=Command(c,tx,"SELECT Sequence,CanonicalJson,ContentSha256 FROM ScorecardMetrics WHERE ScorecardId=$id ORDER BY Sequence;")){Add(rows,"$id",id);await using var metricReader=await rows.ExecuteReaderAsync(ct);int sequence=0;while(await metricReader.ReadAsync(ct)){string json=metricReader.GetString(1);if(metricReader.GetInt32(0)!=sequence++||DeterministicIdentity.Sha256(json)!=metricReader.GetString(2))throw new PersistenceIntegrityException("Scorecard metric integrity failure.");metrics.Add(JsonSerializer.Deserialize<ScorecardMetric>(json,CanonicalJson.SerializerOptions)??throw new PersistenceIntegrityException("Scorecard metric JSON invalid."));}}try{ScoreMetricContract.Validate(metrics);}catch(ArgumentException e){throw new PersistenceIntegrityException("Scorecard metric contract failure: "+e.Message);}if(metrics.Count!=request.Metrics.Count||CanonicalJson.Serialize(metrics)!=CanonicalJson.Serialize(request.Metrics)||request.ScorecardId!=id||request.RunId!=runId||request.RevealId!=reveal||request.ScoringModelVersion!=version||request.InputSha256!=inputHash||request.HeadlineMetric!=headline||request.CreatedValidTimeUtc!=Parse(validText))throw new PersistenceIntegrityException("Scorecard output and metric rows differ.");return new(id,runId,scenario,reveal,version,inputHash,input,output,outputHash,headline,metrics,Parse(validText));
 }
 static async Task<string?> ReadScorecardReceiptAsync(SqliteConnection c,SqliteTransaction? tx,string scorecardId,CancellationToken ct){await using var query=Command(c,tx,"SELECT CanonicalReceiptJson,ReceiptHash FROM ScorecardReceipts WHERE ScorecardId=$id;");Add(query,"$id",scorecardId);await using var reader=await query.ExecuteReaderAsync(ct);if(!await reader.ReadAsync(ct))return null;string json=reader.GetString(0);if(DeterministicIdentity.Sha256(json)!=reader.GetString(1))throw new PersistenceIntegrityException("Scorecard receipt integrity failure.");return json;}
 const string ScoringSchema="""
 CREATE TABLE IF NOT EXISTS Scorecards(ScorecardId TEXT PRIMARY KEY,RunId TEXT NOT NULL UNIQUE,ScenarioId TEXT NOT NULL,RevealId TEXT NOT NULL UNIQUE,ScoringModelVersion TEXT NOT NULL,InputSha256 TEXT NOT NULL,CanonicalInputJson TEXT NOT NULL,HeadlineMetric TEXT NOT NULL,CanonicalOutputJson TEXT NOT NULL,OutputSha256 TEXT NOT NULL,CreatedValidTimeUtc TEXT NOT NULL,CreatedUtc TEXT NOT NULL,FOREIGN KEY(RunId)REFERENCES Runs(RunId));
 CREATE TABLE IF NOT EXISTS ScorecardMetrics(ScorecardId TEXT NOT NULL,Sequence INTEGER NOT NULL,Name TEXT NOT NULL,Basis TEXT NOT NULL,Status TEXT NOT NULL,Value REAL NULL,Unit TEXT NULL,LowerBound REAL NULL,UpperBound REAL NULL,Limitation TEXT NULL,CanonicalJson TEXT NOT NULL,ContentSha256 TEXT NOT NULL,PRIMARY KEY(ScorecardId,Sequence),UNIQUE(ScorecardId,Name),FOREIGN KEY(ScorecardId)REFERENCES Scorecards(ScorecardId));
 CREATE TABLE IF NOT EXISTS ScorecardDeliveries(ScorecardId TEXT PRIMARY KEY,Status TEXT NOT NULL,AttemptCount INTEGER NOT NULL,Diagnostic TEXT NULL,UpdatedUtc TEXT NOT NULL,FOREIGN KEY(ScorecardId)REFERENCES Scorecards(ScorecardId));
 CREATE TABLE IF NOT EXISTS ScorecardReceipts(ScorecardId TEXT PRIMARY KEY,CanonicalReceiptJson TEXT NOT NULL,ReceiptHash TEXT NOT NULL,ReceivedUtc TEXT NOT NULL,FOREIGN KEY(ScorecardId)REFERENCES Scorecards(ScorecardId));
 CREATE TRIGGER IF NOT EXISTS TR_Scorecards_NoUpdate BEFORE UPDATE ON Scorecards BEGIN SELECT RAISE(ABORT,'Scorecards are immutable');END;CREATE TRIGGER IF NOT EXISTS TR_Scorecards_NoDelete BEFORE DELETE ON Scorecards BEGIN SELECT RAISE(ABORT,'Scorecards are immutable');END;
 CREATE TRIGGER IF NOT EXISTS TR_ScorecardMetrics_NoUpdate BEFORE UPDATE ON ScorecardMetrics BEGIN SELECT RAISE(ABORT,'Scorecard metrics are immutable');END;CREATE TRIGGER IF NOT EXISTS TR_ScorecardMetrics_NoDelete BEFORE DELETE ON ScorecardMetrics BEGIN SELECT RAISE(ABORT,'Scorecard metrics are immutable');END;
 CREATE TRIGGER IF NOT EXISTS TR_ScorecardReceipts_NoUpdate BEFORE UPDATE ON ScorecardReceipts BEGIN SELECT RAISE(ABORT,'Scorecard receipts are immutable');END;CREATE TRIGGER IF NOT EXISTS TR_ScorecardReceipts_NoDelete BEFORE DELETE ON ScorecardReceipts BEGIN SELECT RAISE(ABORT,'Scorecard receipts are immutable');END;
 """;
}

public sealed class ScoreCoordinator(DrillingOperationsStore store,AnalysisVerificationClient analysis,AnalysisScorecardClient callback)
{
 public async Task<ApiOutcome> ScoreAsync(string route,string key,string runId,CancellationToken ct)
 {
  await ScoringCorrectionCoordinator.MutationGate.WaitAsync(ct);
  try{return await ScoreCoreAsync(route,key,runId,ct);}
  finally{ScoringCorrectionCoordinator.MutationGate.Release();}
 }
 async Task<ApiOutcome> ScoreCoreAsync(string route,string key,string runId,CancellationToken ct)
 {
  string request=CanonicalJson.Serialize(new{runId});ApiOutcome? replay=await store.TryReplayAsync(route,key,request,ct);if(replay is not null)return replay;ApiOutcome outcome;
  try
  {
   RunResponse run=await store.GetRunAsync(runId,ct)??throw new ScoringException(404,"RunMissing","Run not found.");if(run.Status==RunStatus.Scored){outcome=Json(200,(await store.GetScorecardAsync(runId,ct))!);return await Save();}ScorecardDraft? card=await store.GetScoringCheckpointAsync(runId,ct);bool retry=card is not null&&run.CurrentStage==RunStageKind.S9Score&&run.Status is RunStatus.Running or RunStatus.AwaitingDependency;if(card is null&&run.Status!=RunStatus.Revealed||card is not null&&!retry)throw new ScoringException(409,"RevealNotPublished","Scoring requires an exact completed S8 reveal.");
   if(card is null){card=await CreateAsync(run,ct);await store.PersistScorecardAsync(card,ct);}string? receipt=await store.GetScorecardReceiptAsync(card.ScorecardId,ct);if(receipt is null){var body=JsonSerializer.Deserialize<AnalysisScorecardRequest>(card.CanonicalOutputJson,CanonicalJson.SerializerOptions)!;receipt=await callback.PublishAsync(card.ScenarioId,body,ct);await store.CompleteScorecardAsync(card,receipt,ct);}outcome=Json(200,(await store.GetScorecardAsync(runId,ct))!);
  }
  catch(ScoringException e)when(e.StatusCode is 502 or 503){if(await store.GetScoringCheckpointAsync(runId,ct)is not null)await store.MarkScorecardDeferredAsync(runId,e.DiagnosticCode,ct);outcome=Problem(503,e.Message);}
  catch(ScoringException e){if(e.DiagnosticCode!="RevealNotPublished")await store.FailScorecardAsync(runId,e.DiagnosticCode,ct);outcome=Problem(e.StatusCode,e.Message);}
  catch(PersistenceIntegrityException e){await store.FailScorecardAsync(runId,"ScorecardIntegrityFailure",ct);outcome=Problem(409,e.Message);}
  return await Save();async Task<ApiOutcome> Save()=>await store.ExecuteIdempotentAsync(route,key,request,(_,_,_)=>Task.FromResult(outcome),ct);
 }
 Task<ScorecardDraft> CreateAsync(RunResponse run,CancellationToken ct)=>CalculateForCorrectionAsync(run,false,ct);
 internal async Task<ScorecardDraft> CalculateForCorrectionAsync(RunResponse run,bool legacyBounds,CancellationToken ct)
 {
  if(!Guid.TryParse(run.ScenarioId,out Guid scenarioId))throw new ScoringException(409,"ScoringIdentityMismatch","Scenario identity is invalid.");PublicationStaging plan=await store.GetPublicationAsync(run.RunId,ct)??throw new ScoringException(409,"RevealManifestMissing","Final reveal manifest is missing.");string receiptJson=await store.GetFinalPublicationReceiptAsync(plan.PublicationPlanId,ct)??throw new ScoringException(409,"RevealReceiptMissing","Final reveal receipt is missing.");AnalysisRevealReceipt reveal=JsonSerializer.Deserialize<AnalysisRevealReceipt>(receiptJson,CanonicalJson.SerializerOptions)??throw new ScoringException(409,"RevealReceiptIntegrityMismatch","Final reveal receipt is malformed.");if(reveal.Status!="Revealed"||reveal.ScenarioId!=scenarioId||reveal.RevealId.ToString("D")!=plan.RevealId||reveal.ManifestSha256!=plan.ManifestHash)throw new ScoringException(409,"RevealReceiptIntegrityMismatch","Final reveal receipt does not match the immutable reveal manifest.");
  TruthBindingResponse binding=await store.GetBindingAsync(run.ScenarioId,ct)??throw Missing("Truth binding");(AnalysisScenarioDto scenario,AnalysisPredictionDto prediction) authoritative;try{authoritative=await analysis.GetAsync(scenarioId,ct);}catch(BindingVerificationException e){throw new ScoringException(e.StatusCode>=500?503:409,e.StatusCode>=500?"ScoringAnalysisUnavailable":"ScoringPredictionMismatch",e.Message,e);}if(authoritative.scenario.ScenarioId!=scenarioId)throw new ScoringException(409,"ScoringPredictionMismatch","Authoritative scenario changed.");ScoreArtifactIntegrity.ValidatePrediction(scenarioId,authoritative.prediction,binding.ApprovedSealedPredictionHash,binding.SourcePackageSha256);
  TruthSampleBatch truthBatch=await store.GetTruthSampleBatchAsync(run.RunId,ct)??throw Missing("Truth sample batch");StageATruthResultDto truth=JsonSerializer.Deserialize<StageATruthResultDto>(truthBatch.CanonicalResponseJson,CanonicalJson.SerializerOptions)??throw Missing("Truth sample response");SurveyArtifact survey=await store.GetSurveyArtifactAsync(run.RunId,ct)??throw Missing("Survey artifact");LogObservationArtifact logs=await store.GetLogObservationBatchAsync(run.RunId,ct)??throw Missing("Log observation batch");CompletionDesign completion=await store.GetCompletionDesignAsync(run.RunId,ct)??throw Missing("Completion design");ProductionRunResponse productionTruth=await store.GetProductionTruthAsync(run.RunId,ct)??throw Missing("Production truth");ProductionSeriesArtifact series=await store.GetProductionSeriesAsync(run.RunId,ct)??throw Missing("Production series");
  IReadOnlyList<ScorecardMetric> metrics=legacyBounds
